class.description:
Carries the requester, the clamped view tick, and the correlation key the optimistic effect was armed under. An authority method calls [method bind] before adding a spawned entity to the tree, or [method deny] when validation rejects the request.
[codeblock]
func _place_bomb(ctx: NetwActionContext) -> void:
    var past := lag.sample(entity, ctx.view_tick)
    if past.is_empty():
        ctx.deny()
        return
    var bomb := BOMB.instantiate()
    ctx.bind(bomb)
    bombs.add_child(bomb)
[/codeblock]
